// @vitest-environment node
import { readFileSync } from 'node:fs'
import { describe, expect, it, vi } from 'vitest'
import { buildServiceWorker } from './plugin.ts'

// These tests run the real service-worker code (as generated by the build
// plugin) against a small in-memory imitation of the service-worker globals.

const origin = 'https://rewind.tail1234.ts.net'
const template = readFileSync(new URL('./service-worker.js', import.meta.url), 'utf8')
const shell = ['/assets/index-abc123.js', '/assets/index-def456.css', '/offline.html', '/offline.css', '/manifest.webmanifest', '/icons/icon-192.png']

interface FakeRequest {
  method: string
  url: string
  mode: string
  headers: Headers
}

function req(path: string, init: { method?: string; mode?: string; headers?: Record<string, string> } = {}): FakeRequest {
  return {
    method: init.method ?? 'GET',
    url: path.startsWith('http') ? path : origin + path,
    mode: init.mode ?? 'cors',
    headers: new Headers(init.headers),
  }
}

type Listener = (event: unknown) => void

function setup(opts: { files?: string[]; existing?: string[]; fail?: (url: string) => boolean } = {}) {
  const files = opts.files ?? shell
  const code = buildServiceWorker(template, files.map((url) => ({ url, content: 'content of ' + url })))
  const version = JSON.parse(/const MANIFEST = (\{.*\})/.exec(code)![1]).version as string
  const store = new Map<string, Map<string, Response>>()
  for (const name of opts.existing ?? []) store.set(name, new Map())
  const network = vi.fn(async (r: Request | FakeRequest) => {
    const url = r.url
    if (opts.fail?.(url)) throw new TypeError('Failed to fetch')
    return new Response('network: ' + new URL(url).pathname, { status: 200 })
  })
  const put = vi.fn(() => {
    throw new Error('runtime caching is not allowed')
  })
  const caches = {
    open: async (name: string) => {
      if (!store.has(name)) store.set(name, new Map())
      const entries = store.get(name)!
      return {
        addAll: async (requests: Request[]) => {
          for (const r of requests) {
            const res = await network(r)
            if (!res.ok) throw new TypeError('bad response')
            entries.set(r.url, res)
          }
        },
        match: async (r: string | { url: string }) => entries.get(typeof r === 'string' ? new URL(r, origin).href : r.url)?.clone(),
        put,
      }
    },
    keys: async () => [...store.keys()],
    delete: async (name: string) => store.delete(name),
  }
  const listeners: Record<string, Listener> = {}
  const self = {
    location: { href: origin + '/sw.js', origin },
    addEventListener: (type: string, fn: Listener) => (listeners[type] = fn),
    skipWaiting: vi.fn(async () => {}),
    clients: { claim: vi.fn(async () => {}) },
  }
  new Function('self', 'caches', 'fetch', code)(self, caches, network)

  const lifecycle = async (type: 'install' | 'activate') => {
    let wait: Promise<unknown> = Promise.resolve()
    listeners[type]({ waitUntil: (p: Promise<unknown>) => (wait = p) })
    await wait
  }
  const fetchEvent = (request: FakeRequest): Promise<Response> | undefined => {
    let responded: Promise<Response> | undefined
    listeners.fetch({ request, respondWith: (p: Promise<Response>) => (responded = Promise.resolve(p)) })
    return responded
  }
  return { self, store, network, put, version, cacheName: 'rewind-shell-' + version, lifecycle, fetchEvent }
}

describe('service worker install and activate', () => {
  it('caches exactly the versioned shell, bypassing the HTTP cache', async () => {
    const sw = setup()
    await sw.lifecycle('install')
    const cached = [...sw.store.get(sw.cacheName)!.keys()].map((u) => new URL(u).pathname)
    expect(cached.sort()).toEqual([...shell].sort())
    expect(cached.some((p) => p.startsWith('/api') || p === '/' || p === '/index.html')).toBe(false)
    for (const call of sw.network.mock.calls) expect((call[0] as Request).cache).toBe('reload')
    expect(sw.self.skipWaiting).toHaveBeenCalled()
  })

  it('does not activate a half-cached version when a shell file fails to download', async () => {
    const sw = setup({ fail: (url) => url.endsWith('.css') })
    await expect(sw.lifecycle('install')).rejects.toThrow()
    expect(sw.self.skipWaiting).not.toHaveBeenCalled()
  })

  it('deletes caches from older versions only', async () => {
    const sw = setup({ existing: ['rewind-shell-0123456789abcdef', 'rewind-shell-old', 'someone-elses-cache'] })
    await sw.lifecycle('install')
    await sw.lifecycle('activate')
    expect([...sw.store.keys()].sort()).toEqual([sw.cacheName, 'someone-elses-cache'].sort())
    expect(sw.self.clients.claim).toHaveBeenCalled()
  })

  it('derives a new version when any cached file changes', () => {
    const a = buildServiceWorker(template, [{ url: '/offline.html', content: 'one' }])
    const b = buildServiceWorker(template, [{ url: '/offline.html', content: 'two' }])
    const again = buildServiceWorker(template, [{ url: '/offline.html', content: 'one' }])
    expect(a).not.toBe(b)
    expect(a).toBe(again)
  })
})

describe('service worker fetch policy', () => {
  const bypassed: [string, FakeRequest][] = [
    ['sign-in', req('/api/auth/login', { method: 'POST' })],
    ['session check', req('/api/auth/me')],
    ['auth status', req('/api/auth/status')],
    ['library data', req('/api/tracks?page=1&limit=50')],
    ['bare /api', req('/api')],
    ['audio stream', req('/api/tracks/7/stream')],
    ['audio stream with Range', req('/api/tracks/7/stream', { headers: { Range: 'bytes=1000-' } })],
    ['stream opened as a page', req('/api/tracks/7/stream', { mode: 'navigate' })],
    ['Range on a shell file', req('/assets/index-abc123.js', { headers: { Range: 'bytes=0-10' } })],
    ['non-GET on a shell file', req('/offline.html', { method: 'POST' })],
    ['shell file with a query', req('/assets/index-abc123.js?x=1')],
    ['unknown file', req('/robots.txt')],
    ['other origin', req('https://evil.example/assets/index-abc123.js')],
    ['other origin page', req('https://evil.example/', { mode: 'navigate' })],
  ]

  it.each(bypassed)('never intercepts: %s', async (_name, request) => {
    const sw = setup()
    await sw.lifecycle('install')
    sw.network.mockClear()
    expect(sw.fetchEvent(request)).toBeUndefined()
    expect(sw.network).not.toHaveBeenCalled()
  })

  it('serves versioned shell files from the cache without the network', async () => {
    const sw = setup()
    await sw.lifecycle('install')
    sw.network.mockClear()
    const res = await sw.fetchEvent(req('/assets/index-abc123.js'))!
    expect(await res.text()).toBe('network: /assets/index-abc123.js') // the copy stored at install time
    expect(sw.network).not.toHaveBeenCalled()
  })

  it('falls back to the network for a shell file missing from the cache', async () => {
    const sw = setup()
    const res = await sw.fetchEvent(req('/offline.css'))!
    expect(await res.text()).toBe('network: /offline.css')
    expect(sw.network).toHaveBeenCalledTimes(1)
  })

  it('sends page navigations to the network and does not cache them', async () => {
    const sw = setup()
    await sw.lifecycle('install')
    const before = sw.store.get(sw.cacheName)!.size
    const res = await sw.fetchEvent(req('/', { mode: 'navigate' }))!
    expect(await res.text()).toBe('network: /')
    expect(sw.store.get(sw.cacheName)!.size).toBe(before)
    expect(sw.put).not.toHaveBeenCalled()
  })

  it('shows the cached offline page when a navigation fails', async () => {
    let offline = false
    const sw = setup({ fail: () => offline })
    await sw.lifecycle('install')
    offline = true
    const res = await sw.fetchEvent(req('/#/library', { mode: 'navigate' }))!
    expect(await res.text()).toBe('network: /offline.html')
  })

  it('answers with a plain message when offline before anything was cached', async () => {
    const sw = setup({ fail: () => true })
    const res = await sw.fetchEvent(req('/', { mode: 'navigate' }))!
    expect(res.status).toBe(503)
    expect(await res.text()).toMatch(/cannot reach its server/)
  })

  it('never writes to the cache at runtime', async () => {
    const sw = setup()
    await sw.lifecycle('install')
    const before = sw.store.get(sw.cacheName)!.size
    for (const [, request] of bypassed) sw.fetchEvent(request)
    await sw.fetchEvent(req('/assets/index-abc123.js'))
    await sw.fetchEvent(req('/', { mode: 'navigate' }))
    expect(sw.put).not.toHaveBeenCalled()
    expect(sw.store.get(sw.cacheName)!.size).toBe(before)
  })
})
